5	/**
6	 * The unified member identifier, formatted {@code <REGION><FY><HASH8><CHK>}: the region
7	 * code, the 2-digit fiscal year, the 8 upper-hex HASH8 (see {@link AssignCustomerCode}) and
8	 * a single Luhn check digit over the digits of {@code <REGION><FY><HASH8>}. The three
9	 * trailing segments are fixed width, so the region is whatever precedes them.
10	 */
11	public final class MemberId {
12	
13	    private static final int HASH8_LEN = 8;
14	    private static final int FY_LEN = 2;
15	    private static final int TAIL = FY_LEN + HASH8_LEN + 1; // FY + HASH8 + CHK
16	
17	    private MemberId() {
18	    }
19	
20	    /** Builds the id from its region, the fiscal year of {@code registrationDate} and HASH8. */
21	    public static String of(String region, LocalDate registrationDate, String hash8) {
22	        String body = String.format("%s%02d%s", region, FiscalYear.of(registrationDate) % 100, hash8);
23	        return body + CheckDigit.of(body);
24	    }
25	
26	    /** The region segment: everything before the fixed-width tail. */
27	    public static String region(String memberId) {
28	        return memberId.substring(0, memberId.length() - TAIL);
29	    }
30	
31	    /** The {@code FY<YY>} label carried by the id. */
32	    public static String fiscalYear(String memberId) {
33	        int fyEnd = memberId.length() - (HASH8_LEN + 1);
34	        return "FY" + memberId.substring(fyEnd - FY_LEN, fyEnd);
35	    }
36	}
