1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateTelephoneException;
8	
9	/**
10	 * Consolidated duplicate check replacing the former separate telephone, email and
11	 * household checks, run before {@link BuildOwner}. Duplicate detection now turns on the
12	 * derived {@link IdentityKey} (SHA-256 over normalized telephone, lower email and
13	 * soundex(lastName)): two owners collide exactly when that whole key matches. Because the
14	 * telephone is part of the key, same-household owners with different telephones have
15	 * different keys and are both allowed (a soft match, not a 409). Owners flagged deleted are
16	 * ignored; the email-domain blocklist has already been applied by the earlier email step.
17	 */
18	public class RequireUniqueIdentity {
19	
20	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
21	            throws DuplicateTelephoneException {
22	        String key = IdentityKey.of(request.getTelephone(), request.getEmail(),
23	                request.getLastName(), request.getPostcode());
24	        for (Owner existing : ownerRepository.findAll()) {
25	            if (existing.isDeleted()) {
26	                continue;
27	            }
28	            if (key.equals(IdentityKey.of(existing.getTelephone(), existing.getEmail(),
29	                    existing.getLastName(), existing.getPostcode()))) {
30	                throw new DuplicateTelephoneException(request.getTelephone());
31	            }
32	        }
33	    }
34	}
