9	/**
10	 * Rejects a create-owner request that resolves to the same {@link HouseholdId} (derived
11	 * from lastName and postcode) as an existing owner, before {@link BuildOwner} runs. A
12	 * request may opt out by setting {@code sharesHousehold} true, which permits a deliberately
13	 * declared household member; the flag only bypasses this block and does not affect the
14	 * derived householdId. Requests without a postcode have no household and are left untouched.
15	 */
16	public class RequireUniqueHousehold {
17	
18	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
19	            throws DuplicateHouseholdException {
20	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
21	            return;
22	        }
23	        String postcode = request.getPostcode();
24	        if (postcode == null || postcode.isBlank()) {
25	            return;
26	        }
27	        String householdId = HouseholdId.of(request.getLastName(), postcode);
28	        for (Owner existing : ownerRepository.findAll()) {
29	            if (existing.isDeleted()) {
30	                continue;
31	            }
32	            if (householdId.equals(HouseholdId.of(existing.getLastName(), existing.getPostcode()))) {
33	                throw new DuplicateHouseholdException(request.getLastName(), postcode);
34	            }
35	        }
36	    }
37	}
