package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Assigns the unified {@code memberId} (see {@link MemberId}). REGION is derived from the
 * postcode (see {@link Locality}) and HASH8 is the first 8 upper-case hex characters of
 * SHA-256 over the normalised telephone plus lastName.
 */
public class AssignCustomerCode {

    public void service(@Val Owner owner) {
        String region = Locality.of(owner.getCity(), owner.getPostcode());
        String hash8 = hash8(E164Telephone.toE164(owner.getTelephone()) + owner.getLastName());
        owner.setCustomerCode(MemberId.of(region, owner.getRegistrationDate(), hash8));
    }

    private static String hash8(String value) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                .digest(value.getBytes(StandardCharsets.UTF_8));
            StringBuilder hex = new StringBuilder();
            for (int i = 0; i < 4; i++) {
                hex.append(String.format("%02X", digest[i]));
            }
            return hex.toString();
        } catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException(ex);
        }
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

/**
 * Derives the stable {@code householdId} shared by owners with the same lastName and
 * postcode. It is the first 12 hex characters of SHA-256 over
 * {@code normalizedLastName + '|' + postcode}, where the lastName is compared
 * case-insensitively with collapsed whitespace, so co-resident same-lastName owners always
 * resolve to one identifier.
 */
public final class HouseholdId {

    private HouseholdId() {
    }

    public static String of(String lastName, String postcode) {
        String key = normalise(lastName) + '|' + (postcode == null ? "" : postcode);
        return sha256Hex(key).substring(0, 12);
    }

    private static String normalise(String value) {
        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
    }

    private static String sha256Hex(String value) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(digest.length * 2);
            for (byte b : digest) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        }
        catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException(e);
        }
    }
}

